{
  "sql": "SELECT t1.product_category_name_english, ROUND(SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT t3.order_id), 2) AS pct_pagos_a_plazos FROM product_category_translation t1 LEFT JOIN products t2 ON t1.product_category_name = t2.product_category_name LEFT JOIN order_payments t3 ON t3.order_id = t2.order_id WHERE t3.payment_type != 'not_defined' GROUP BY t1.product_category_name_english HAVING COUNT(DISTINCT t3.order_id) >= 100 ORDER BY pct_pagos_a_plazos DESC LIMIT 1"
}

